curl -sL "https://www.imf.org/en/Publications/WEO/weo-database/2024/October/weo-report?c=915&s=NGDP_R,NGDP_RPCH,NGDP,NGDPD,NGDP_D,PPPEX,LP&sy=2020&ey=2029&ssm=0&scsm=1&scc=0&ssd=1&ssc=0&sic=0&sort=country&ds=.&br=1" -o /root/weo_page.html 2>&1 && python3 -c "
import json, re
with open('/root/weo_page.html','r') as f:
    content = f.read()
# Find the NEXT_DATA json
match = re.search(r'<script id=\"__NEXT_DATA__\" type=\"application/json\">(.*?)</script>', content, re.DOTALL)
if match:
    data = json.loads(match.group(1))
    # Navigate to find the actual WEO data
    props = data.get('props',{}).get('pageProps',{})
    # Look for any key containing data
    def find_keys(d, prefix=''):
        if isinstance(d, dict):
            for k,v in d.items():
                if any(word in str(k).lower() for word in ['data','value','country','gdp','georgia']):
                    if isinstance(v, (str, int, float)):
                        print(f'{prefix}.{k} = {str(v)[:200]}')
                    elif isinstance(v, list) and len(v) < 20:
                        print(f'{prefix}.{k} = list({len(v)})')
                find_keys(v, f'{prefix}.{k}')
        elif isinstance(d, list):
            for i, item in enumerate(d[:5]):
                find_keys(item, f'{prefix}[{i}]')
    find_keys(props)
else:
    print('No NEXT_DATA found')
" 2>&1 | head -50

